class AerodromeCloudForecastType(AbstractGmltype):
    """
    Parameters
    ----------
    vertical_visibility
        The vertical visibility.  Vertical visibility is defined as the vertical visual range into an obscuring
        medium. Vertical visibility shall be reported either in meters ("m") or feet ("[ft_i]").
    layer
        Description of individual layer of cloud.
    extension
        Extension block for optional and/or additional parameters for element AerodromeCloudForecast
    """

    model_config = ConfigDict(defer_build=True)
    vertical_visibility: None | LengthWithNilReasonType = field(
        default=None,
        metadata={
            "name": "verticalVisibility",
            "type": "Element",
            "namespace": "http://icao.int/iwxxm/2023-1",
            "nillable": True,
        },
    )
    layer: list[CloudLayerPropertyType] = field(
        default_factory=list,
        metadata={
            "type": "Element",
            "namespace": "http://icao.int/iwxxm/2023-1",
            "max_occurs": 4,
        },
    )
    extension: list[ExtensionType] = field(
        default_factory=list,
        metadata={
            "type": "Element",
            "namespace": "http://icao.int/iwxxm/2023-1",
        },
    )


class AerodromeCloudForecast(AerodromeCloudForecastType):
    """
    Forecast cloud conditions, including predicted vertical visibility and cloud layers.

    A single vertical visibility may be reported, but cannot be reported with cloud layers.
    """

    class Meta:
        namespace = "http://icao.int/iwxxm/2023-1"

    model_config = ConfigDict(defer_build=True)


